from pathlib import Path
import html
P=Path('docs/system-analysis/diagrams')
def make(name,title,nodes,edges,w=1000,h=600):
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}"><rect width="100%" height="100%" fill="white"/><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 Z" fill="#48647d"/></marker></defs>',f'<text x="30" y="30" font-family="Arial" font-size="22" fill="#142c45">{title}</text>']
 for points,label,lx,ly,dashed,arrow in edges:
  s.append(f'<polyline points="{points}" fill="none" stroke="#48647d" stroke-width="2"'+(' stroke-dasharray="6,4"' if dashed else '')+(' marker-end="url(#a)"' if arrow else '')+'/>');s.append(f'<text x="{lx}" y="{ly}" font-family="Arial" font-size="17" fill="#142c45">{html.escape(label)}</text>')
 for x,y,ww,hh,lines,kind in nodes:
  s.append(f'<rect x="{x}" y="{y}" width="{ww}" height="{hh}" rx="{12 if kind=="state" else 0}" fill="#f3f6f9" stroke="#48647d" stroke-width="2"/>')
  for i,line in enumerate(lines):s.append(f'<text x="{x+12}" y="{y+28+i*25}" font-family="Arial" font-size="{16 if len(line)>24 else 18}" fill="#142c45">{html.escape(line)}</text>')
  if kind=='class':s.append(f'<line x1="{x}" y1="{y+38}" x2="{x+ww}" y2="{y+38}" stroke="#48647d"/>')
 s.append('</svg>');(P/(name+'.svg')).write_text(''.join(s))
